(function(){var d={"book": {"chapters": [{"blocks": [{"args": [{"s": "L5R5e_Core_Core"}], "kw": "DEPENDS_ON"}, {"ent": "#lKIp7ISJxHs1XKKEPNzpNZ"}, {"ent": "#0sb0csLT4xayKYIKaXvynp"}, {"ent": "#H39Fu7eQrvB4ZxD5U5zXLz"}], "container": "EXTENSION", "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "kind": "ttrpg", "module": "L5R5e_MaskOfTheOni_Cast", "page": null, "roots": ["#lKIp7ISJxHs1XKKEPNzpNZ", "#0sb0csLT4xayKYIKaXvynp", "#H39Fu7eQrvB4ZxD5U5zXLz"]}, {"blocks": [{"args": [{"s": "l5r5e"}], "kw": "SYSTEM"}, {"args": [{"s": "Mask of the Oni: An Adventure in the Shadowlands (Fantasy Flight Games, product L5R07)"}], "kw": "SOURCE"}, {"args": [{"s": "Fantasy Flight Games"}], "kw": "LEAD_WRITER"}, {"args": [{"s": "Mask of the Oni is an adventure for the Legend of the Five Rings Roleplaying Game. During the course of this adventure, the player characters leave the relative security of the Emerald Empire and pass through the lands and defenses of the Crab Clan to the Shadowlands. This perilous journey takes them to the ruins of Shiro Hiruma, the once-proud stronghold of the Hiruma family of the Crab. There, the characters must face dangerous opponents, stark horror, and their deepest fears if they wish to succeed in stopping a powerful blood magic practitioner, a mahō-tsukai, from achieving her nefarious goals."}], "kw": "DESCRIPTION"}, {"args": [{"l": [{"s": "The vigil of the Crab against the Shadowlands"}, {"s": "Honor and sacrifice — Hiruma Masami's ritual"}, {"s": "Blood magic and the corruption of the fallen"}, {"s": "Facing one's deepest fears in a defiled place"}, {"s": "A castle's burning shame reclaimed"}]}], "kw": "THEMES"}, {"args": [{"s": "Shadowlands horror: a perilous journey past the Kaiu Wall into a Tainted, shifting hellscape, culminating in a defiled ruin and a battle against a mahō-tsukai and an oni"}], "kw": "TONE"}, {"args": [{"s": "The players' own characters (no pregens); Crab-connected PCs ideal"}], "kw": "PLAYER_COUNT"}, {"args": [{"s": "The Crab lands, the Kaiu Wall, and the Shadowlands beyond, to the ruins of Shiro Hiruma; the year 1123"}], "kw": "SETTING"}, {"args": [{"s": "Centuries ago the oni Atsumari no Oni led the Shadowlands assault that felled Shiro Hiruma; the shugenja Hiruma Masami sacrificed her life and her very name to enact a ritual — sealed by three keys — that sent the souls of the last Hiruma defenders to Yume-dō, safe from corruption, and banished the oni to Jigoku. Now the mahō-tsukai Kitsu Sokori — a Lion Kitsu fallen to blood magic — has pieced together that history and journeys to the ruined castle to assemble the three keys, unravel Masami's ritual, release the Hiruma souls, and strike a deal with the returning Atsumari no Oni to corrupt them into her army. The PCs travel through the Crab lands (Part Two), brave the Shadowlands (Part Three), explore the defiled ruin and recover the keys and the stolen maps of Yasuki Keiji (Part Four), and confront Sokori and the oni in a final battle for the souls of the Hiruma (Part Five)."}], "kw": "SUMMARY"}, {"args": [], "body": [{"args": [{"i": 1}, {"s": "Part One: Adventure Background"}], "body": [{"args": [{"l": [{"s": "The Fall of Daylight"}, {"s": "The Fate of the Hiruma"}, {"s": "Hiruma Masami's Ritual and the Three Keys"}, {"s": "The Involvement of Kitsu Sokori"}, {"s": "The Dark Tides Connection"}]}], "kw": "SCENES"}, {"args": [{"s": "The historical and secret background (much of it GM-only). In the eighth century the oni Atsumari no Oni felled Shiro Hiruma; Hiruma Masami — born of the Kaikoga family of the Moth Clan, married into the Hiruma — enacted a complex ritual, sealed by three keys and empowered by her surrendered name, that sent the last defenders' souls to Yume-dō and banished the oni to Jigoku, sacrificing herself to Yume-dō in the process. The three keys can also unravel the ritual: the final passage of Masami's ritual spoken aloud, the wakizashi of the Hiruma daimyō, and Masami's name (recorded only on a hidden scroll in the castle library). Kitsu Sokori, introduced in Dark Tides, seeks to exploit all of this."}], "kw": "DESCRIPTION"}], "kw": "PART"}, {"args": [{"i": 2}, {"s": "Part Two: Arriving at the Kaiu Wall"}], "body": [{"args": [{"l": [{"s": "The Kaiu Wall"}, {"s": "Yasuki Ippei, Crooked Quartermaster"}, {"s": "Kaiu Riko, Gruff Engineer"}, {"s": "Convincing Hida Hachirō"}, {"s": "A Crab Escort (Hida Nagahide)"}]}], "kw": "SCENES"}, {"args": [{"s": "The PCs reach the hundred-foot Kaiu Wall amid the aftermath of a recent battle. They must secure supplies (jade and food) from the furtive quartermaster Yasuki Ippei, may learn the castle's history from the gruff engineer Kaiu Riko, and must convince the Crab (Hida Hachirō, with the Scorpion Bayushi Tsubasa as a fallback) to let them venture beyond the Wall — gaining a Crab escort of bushi under the veteran gunsō Hida Nagahide."}], "kw": "DESCRIPTION"}], "kw": "PART"}, {"args": [{"i": 3}, {"s": "Part Three: Into the Shadowlands"}], "body": [{"args": [{"l": [{"s": "Through the Gate"}, {"s": "The Shifting Landscape"}, {"s": "Shadowlands Horrors"}, {"s": "The Journey to Daylight Castle"}]}], "kw": "SCENES"}, {"args": [{"s": "Nagahide (or Bayushi Tsubasa) leads the PCs beyond the Wall into the Shadowlands for the three-day journey to Shiro Hiruma. The perversely fluid landscape, the Taint, and Shadowlands creatures (goblins, the animate dead, and worse) test the PCs — and demonstrate the horrors that make the Crab's vigil eternal — without overwhelming them before they reach the castle. (Something in the wastes also hunts nezumi blood — a hook toward the Knotted Tails tribe.)"}], "kw": "DESCRIPTION"}], "kw": "PART"}, {"args": [{"i": 4}, {"s": "Part Four: Shadow of Daylight"}], "body": [{"args": [{"l": [{"s": "Arrival at Shiro Hiruma"}, {"s": "Exploring the Defiled Ruin"}, {"s": "The Library and Masami's Scroll"}, {"s": "Recovering the Three Keys"}, {"s": "The Maps of Yasuki Keiji"}]}], "kw": "SCENES"}, {"args": [{"s": "Shiro Hiruma / Daylight Castle is a bleak, Taint-warped ruin, ominous and confusing even for Crab samurai. Exploring it, the PCs recover the three keys to Masami's ritual — including her name, found only on a scroll hidden in the library — and may retrieve the stolen maps of Yasuki Keiji, which drew them into the mission. Throughout, Kitsu Sokori and her undead work toward ending Masami's ritual before the PCs can stop her."}], "kw": "DESCRIPTION"}], "kw": "PART"}, {"args": [{"i": 5}, {"s": "Part Five: The Battle for the Souls of Hiruma"}], "body": [{"args": [{"l": [{"s": "Sokori's Ritual"}, {"s": "The Course of the Battle (Sokori and Atsumari no Oni)"}, {"s": "Freeing the Souls of Hiruma"}, {"s": "Winning the Day / Failure Is an Option"}]}], "kw": "SCENES"}, {"args": [{"s": "The climax. Sokori works to end Masami's ritual and release the Hiruma souls from Yume-dō, calling on Atsumari no Oni — which may ally with her or be a hostile third party — to corrupt them into her army. The PCs, engaged by undead servants, must stop her; assembling all three keys lets them undo the ritual (a TN 4 Theology check, Void 2) and free the Hiruma souls to their judgment in Meido. Victory sends the PCs to Winning the Day; defeat, capture, or retreat to Failure Is an Option. Sokori is expected to die, but the GM may let her escape as a future antagonist."}], "kw": "DESCRIPTION"}], "kw": "PART"}], "kw": "PARTS"}, {"args": [], "body": [{"ent": "#Kk0bICKWg5dzm7RKmKiK6I"}, {"ent": "#k0fyufj3ODA21YOZWPZ59X"}], "kw": "LOCATIONS"}, {"args": [], "body": [{"args": [{"l": [{"c": "Kitsu Sokori"}, {"c": "Atsumari no Oni", "h": "#0sb0csLT4xayKYIKaXvynp"}]}], "kw": "ANTAGONISTS"}, {"args": [{"l": [{"c": "Hida Nagahide", "h": "#H39Fu7eQrvB4ZxD5U5zXLz"}]}], "kw": "ALLIES"}], "kw": "KEY_NPCS"}], "container": "ARC", "file": "l5r5e-0.5-mask-of-the-oni.arc", "kind": "arc", "module": "mask-of-the-oni", "moduleExtends": "l5r5e", "name": "Mask of the Oni", "page": null, "roots": ["#Kk0bICKWg5dzm7RKmKiK6I", "#k0fyufj3ODA21YOZWPZ59X"]}, {"file": "l5r5e-0.5-mask-of-the-oni.lore", "kind": "lore", "name": "# Mask of the Oni — An Adventure in the Shadowlands", "page": null, "text": "# Mask of the Oni — An Adventure in the Shadowlands\n\n**Version:** 0.5.0\n**Source:** Legend of the Five Rings Roleplaying Game — Mask of the Oni (product L5R07)\n**Publisher:** Fantasy Flight Games\n\n> GM-facing narrative. Boxed **read-aloud** text is reproduced verbatim; intervening GM procedure\n> (check TNs, journey bookkeeping, encounter difficulty) is summarized faithfully — the full detail\n> lives in the source PDF. The two full statblocks (Kitsu Sokori, Atsumari no Oni) and the Crab escort\n> leader are in `l5r5e-0.5-mask-of-the-oni-cast.ttrpg`; the act structure in\n> `l5r5e-0.5-mask-of-the-oni.arc`. This adventure uses the players' own characters — Crab-connected PCs\n> are ideal — so there are no pregens. It takes place in 1123. Its villain, Kitsu Sokori, first appears\n> in the *Dark Tides* adventure (Game Master's Kit).\n\n---\n\n## Adventure Background\n\nDuring *Mask of the Oni*, the PCs leave the relative security of the Emerald Empire and pass through the lands and defenses of the Crab Clan into the **Shadowlands**, to the ruins of **Shiro Hiruma** — Daylight Castle, the once-proud stronghold of the Hiruma family. There they must face dangerous opponents, stark horror, and their deepest fears to stop the mahō-tsukai **Kitsu Sokori** from achieving her goals.\n\n### The Fall of Daylight\n\nShiro Hiruma was the Hiruma family's ancestral seat, built to withstand siege — deep wells, storehouses, tunnels, and cunning traps. In the eighth century a new threat rose from the Shadowlands: an oni now called **The Maw** beat the squabbling lieutenants of Fu Leng, and among the forces that felled Shiro Hiruma was **Atsumari no Oni**. The castle's loss remains a burning shame to the Hiruma; many attempts to recover the ruins have failed, and over time the surrounding lands became yet another corrupted region of the Shadowlands.\n\n### The Fate of the Hiruma (and Masami's Ritual)\n\nAtsumari no Oni was never again seen after the castle's fall — because of a ritual performed by a shugenja whose name has been lost to history: **Hiruma Masami**. Born of the **Kaikoga family of the Moth Clan** (a Minor Clan devoted to studying **Yume-dō**, the Realm of Dreams), Masami married into the Hiruma and cared for the temple within Shiro Hiruma. When Atsumari no Oni used its powers of corrupt resurrection to attack, Masami realized the very souls of the family were in danger, and performed a complex ritual ensuring that the souls of the last Hiruma to perish would be sent to **Yume-dō**, safe from corruption. The ritual could not save the castle, but it greatly reduced the oni's power and saved the souls of hundreds of Hiruma samurai. Incensed, the oni turned on Masami — but she had planned for that too, sacrificing her life to send the oni back to **Jigoku** and herself to Yume-dō, where she keeps the saved Hiruma safe to this day.\n\nMasami knew the ritual could not be permanent (that would blasphemously halt the Karmic Wheel), so she bound it with **three keys** — the same keys that can unravel it and let the souls pass on to judgment in **Meido**:\n\n1. **The final passage of Masami's ritual, spoken aloud** — representing the thwarting of the oni's terrible assault upon the Hiruma.\n2. **The wakizashi of the Hiruma family daimyō** — representing the honor of the Hiruma samurai who defended the castle to the last.\n3. **Masami's name**, which she surrendered to empower the ritual — representing her sacrifice. The only recorded instance of her name is on a scroll hidden in the library in Shiro Hiruma; *the GM should ensure her name is not revealed to the PCs except through that scroll.*\n\nBut sinister forces also await the ritual's end. Atsumari no Oni has waited centuries in Jigoku to return and claim the souls it was denied — souls with which it could raise an ever-growing army, avenge itself on Masami, and resume subverting the Crab to open the way for the Shadowlands to overrun the Empire.\n\n### The Involvement of Kitsu Sokori\n\n**Kitsu Sokori** is the daughter of a minor lord of the **Kitsu** family of the **Lion Clan** — a talented shugenja gifted with the Kitsu method of speaking with ancestors. Passed over as her father's heir in favor of her older brother, she murdered him with an ancient **mahō** scroll's blood magic (a slow wasting disease); when her heartbroken father named a distant cousin instead, she left her family's lands vowing to seize power, and became a powerful **mahō-tsukai**.\n\nHer path (detailed in *Dark Tides*) led her to **Slow Tide Harbor** (Tortoise/Kasuga lands), where her abductions drew attention, and then south into Crab lands, using blood taken from Crab samurai only through indirect means. In Soft Breeze Village she abducted and tortured a washed-up rōnin named **Hozumi**, once of the Hiruma family, using mahō and Kitsu ancestor-speaking to summon and question his ancestors — piecing together the history of Shiro Hiruma, Atsumari no Oni, and Masami's ritual. She now travels to Shiro Hiruma to assemble the three keys, end Masami's ritual, release the fallen Hiruma from Yume-dō, and cause Atsumari no Oni to return to Ningen-dō — striking a deal to let the oni corrupt the Hiruma into her personal army, granting her power among the minions of Fu Leng and revenge upon the Lion family she has grown to detest.\n\n### The Dark Tides Connection\n\nSokori is introduced in the *Dark Tides* adventure (Game Master's Kit); if the PCs played it, *Mask of the Oni* is a natural continuation of their involvement with her. It is not required, however, and can begin a new campaign or slot into an ongoing one.\n\n---\n\n## Part Two: Arriving at the Kaiu Wall\n\nThe PCs reach the Kaiu Wall amid the aftermath of a recent battle:\n\n> The Kaiu Wall looms over you, one hundred feet of dark stone battlements, redoubts, and watchtowers standing between Rokugan and the Shadowlands beyond. You pass by signs of a recent battle as you approach: wounded Crab bushi being tended by healers and shugenja, burakumin carrying off the dead to be cremated, and yet more warriors cleaning and repairing armor and weapons. More troops stand guard atop the Wall, as the vigil of the Crab against the darkness never ends.\n\nHere the PCs must:\n\n- **Secure supplies** (jade and food for the journey) from the furtive, selfish quartermaster **Yasuki Ippei**, who is open to \"nonstandard arrangements\" that advance his goal of a post far from the Crab lands. If the PCs are stymied, the Scorpion **Bayushi Tsubasa** — who holds incriminating information about Ippei's forged paperwork — can coerce his cooperation, at the cost of the PCs owing Tsubasa a future favor.\n- **Learn the history** from the gruff engineer **Kaiu Riko**, an expert in ancient Crab fortifications who can be won over with a TN 2 Command check and will tell of the Maw, its attack on Shiro Hiruma, and more.\n- **Win passage** beyond the Wall by convincing the Crab (notably **Hida Hachirō**) that their mission is important — gaining a **Crab escort** of Hida and Hiruma bushi under the veteran gunsō **Hida Nagahide**.\n\n---\n\n## Part Three: Into the Shadowlands\n\n**Hida Nagahide** (or Bayushi Tsubasa) leads the PCs through a heavily defended gate into the Shadowlands for the roughly three-day journey to Shiro Hiruma. The GM should seize on the Shadowlands' perversely **shifting landscape** to keep the players tense and disoriented — lost even when they believe they are not — while showing the horrors that make the Crab's vigil eternal (Shadowlands goblins, the animate dead, exposure to the Taint), without letting the escort NPCs overshadow the PCs or letting the journey drag. The ultimate point is to arrive at Shiro Hiruma. (In the wastes, something also hunts **nezumi** blood — a hook toward the Knotted Tails tribe.)\n\n---\n\n## Part Four: Shadow of Daylight\n\n**Shiro Hiruma / Daylight Castle** is a bleak ruin, warped by battle damage, the passage of time, and the Taint of Jigoku:\n\n> As you round a rocky spur that thrusts out from a line of jagged, barren hills, you see the walls of a fortress looming ahead of you, dominating the blasted landscape around it. This is Shiro Hiruma, ancestral home and seat of power of the Hiruma. Now, it is a bleak ruin, with gaping holes where walls once stood.\n\nExploring the defiled, confusing ruin, the PCs recover the **three keys** to Masami's ritual — including her surrendered **name**, found only on a scroll hidden in the library — and may retrieve the stolen **maps of Yasuki Keiji** that first drew them into the mission (duty-bound to do so even as the greater threat becomes clear). All the while, **Kitsu Sokori** and her undead servants work toward ending Masami's ritual before the PCs can stop her.\n\n---\n\n## Part Five: The Battle for the Souls of Hiruma\n\nThe final confrontation. Sokori works to end Masami's ritual and release the Hiruma souls from Yume-dō — she has even designed her own ritual to do so with only one or two of the keys, at the cost of more time — calling upon **Atsumari no Oni** to corrupt the freed souls into her army. The oni's role is variable: it may ally with Sokori, or be a hostile third party to both her and the PCs.\n\nEngaged first by Sokori's undead, the PCs must stop her. Sokori favors indirect tactics — using **Whispers in Blood** to learn and exploit the PCs' flaws (turning their phobias, paranoia, clan rivalries, and dark secrets against them), her undead to fight in her stead, and **Walking the Way** to escape a losing fight once. Atsumari no Oni relies on **Corrupt the Fallen** to raise bushi skeletons and zombie peasants from the dead of the battle.\n\n**Freeing the Souls of Hiruma:** PCs who assemble all three keys can undo Masami's ritual with a **TN 4 Theology check (Void 2)** — reduced to TN 1 if Masami's scroll instructed them how — releasing the Hiruma souls to their long-delayed judgment in Meido. If the PCs have not slain or banished Atsumari no Oni, the freed souls may still be in danger.\n\nVictory sends the PCs to **Winning the Day**; being killed, captured, or forced to retreat sends them to **Failure Is an Option**. Sokori is expected to die by the end — but the GM may let her escape to trouble the PCs again. Bargaining with either Sokori or the oni is possible, but any bargain made in good faith with such evil beings costs the PCs some honor and glory.\n\n---\n\n## The Cast at a Glance\n\n- **Kitsu Sokori** — the mahō-tsukai villain, a Lion Kitsu fallen to blood magic; introduced in *Dark Tides* (full statblock).\n- **Atsumari no Oni** — the oni that felled Shiro Hiruma, returned from Jigoku to claim the Hiruma souls (full statblock).\n- **Hida Nagahide** — veteran Crab gunsō leading the escort (profile-based, Loyal Bushi).\n- **Yasuki Ippei** — a crooked Crab quartermaster. **Kaiu Riko** — a gruff Crab engineer and historian. **Bayushi Tsubasa** — a Scorpion fixer with leverage over Ippei. **Hida Hachirō** — the Crab who grants passage. (Interaction NPCs; narrative.)\n- **Hiruma Masami** — the Kaikoga/Moth shugenja whose sacrifice saved the Hiruma souls (historical). **The Maw** — the oni that led the eighth-century assault. **Yasuki Keiji** — whose stolen maps drew the PCs in. **Hozumi** — the Hiruma rōnin Sokori tortured for the history. (Narrative figures.)\n"}, {"blocks": [{"args": [], "kw": "FOR"}, {"args": [{"s": "l5r5e"}], "kw": "EDITION"}, {"args": [{"s": "L5R5e_Codex_Schema"}], "kw": "DEPENDS_ON"}, {"ent": "#L5RcxMoO04kaikogafamily"}, {"ent": "#L5RcxMoO01hirumamasami"}, {"ent": "#L5RcxMoO02yasukikeiji"}, {"ent": "#L5RcxMoO03hozumironin"}, {"ent": "#HfpS0mwWcNggGn4LbpFYJj"}, {"ent": "#H21xYNNhIDYRnQDFEJ3r1x"}, {"ent": "#N1WnfOBOWrGonxKItB6LDA"}, {"ent": "#vYRQSaECZpWt7nmleTn86t"}], "container": "CODEX", "file": "l5r5e-0.5-mask-of-the-oni.codex", "kind": "codex", "module": "L5R5e_MaskOfTheOni_Codex", "name": "Mask of the Oni — Lore Graph", "page": null, "roots": ["#L5RcxMoO04kaikogafamily", "#L5RcxMoO01hirumamasami", "#L5RcxMoO02yasukikeiji", "#L5RcxMoO03hozumironin", "#HfpS0mwWcNggGn4LbpFYJj", "#H21xYNNhIDYRnQDFEJ3r1x", "#N1WnfOBOWrGonxKItB6LDA", "#vYRQSaECZpWt7nmleTn86t"]}], "entities": ["#lKIp7ISJxHs1XKKEPNzpNZ", "#0sb0csLT4xayKYIKaXvynp", "#H39Fu7eQrvB4ZxD5U5zXLz", "#Kk0bICKWg5dzm7RKmKiK6I", "#k0fyufj3ODA21YOZWPZ59X", "#L5RcxMoO04kaikogafamily", "#L5RcxMoO01hirumamasami", "#L5RcxMoO02yasukikeiji", "#L5RcxMoO03hozumironin", "#HfpS0mwWcNggGn4LbpFYJj", "#H21xYNNhIDYRnQDFEJ3r1x", "#N1WnfOBOWrGonxKItB6LDA", "#vYRQSaECZpWt7nmleTn86t"], "id": "mask-of-the-oni", "kind": "adventure", "label": "Mask of the Oni"}, "entities": {"#0sb0csLT4xayKYIKaXvynp": {"blocks": [{"ent": "#zNdk7Evn1NAw7w6rbFAKYw"}, {"ent": "#HKD14HWbpCc1ooWIaVFjWA"}, {"ent": "#xN38GbiHCH6QjbMuENI7EL"}], "book": "mask-of-the-oni", "children": ["#zNdk7Evn1NAw7w6rbFAKYw", "#HKD14HWbpCc1ooWIaVFjWA", "#xN38GbiHCH6QjbMuENI7EL"], "desc": "ADVERSARY. Conflict Rank — Combat 12, Intrigue 5. An Otherworldly, Tainted being of silhouette 4.", "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#0sb0csLT4xayKYIKaXvynp", "name": "Atsumari no Oni", "parent": null, "props": [{"dtype": "STRING", "fixed": true, "name": "Type", "value": "Adversary", "vk": "scalar"}, {"dtype": "INTEGER", "name": "Combat Conflict Rank", "value": 12, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Intrigue Conflict Rank", "value": 5, "vk": "scalar"}, {"fields": [{"dtype": "INTEGER", "name": "Air", "value": 3, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Earth", "value": 3, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Fire", "value": 6, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Water", "value": 4, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Void", "value": 4, "vk": "scalar"}], "name": "Rings", "vk": "def"}, {"dtype": "STRING", "name": "Demeanor", "value": "Power-Hungry", "vk": "scalar"}, {"dtype": "INTEGER", "name": "Endurance", "value": 22, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Composure", "value": 14, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Focus", "value": 9, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Vigilance", "value": 4, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Honor", "value": 0, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Glory", "value": 15, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Status", "value": 0, "vk": "scalar"}, {"items": [{"s": "Artisan 0"}, {"s": "Martial 3"}, {"s": "Scholar 3"}, {"s": "Social 1"}, {"s": "Trade 0"}], "name": "Skills", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Massive Stature — Martial; Physical"}, {"s": "Unholy Might — Martial; Physical, Spiritual"}], "name": "Advantages", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Horrifying Visage — Social; Interpersonal"}], "name": "Disadvantages", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Crushing Claws: Range 1-2, Damage 6, Deadliness 8, Razor-Edged, Unholy"}], "name": "Favored Weapons", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Gear (equipped): Demonic hide and armor scraps (Physical 5, Spiritual 5, Unholy)"}], "name": "Gear", "of": "STRING", "ofWord": true, "vk": "list"}], "slot": null, "type": "NPC", "typeHash": "#t4540de6f35155c46f41f0"}, "#H21xYNNhIDYRnQDFEJ3r1x": {"blocks": [{"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-fall-of-daylight"}], "kw": "AT"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#H21xYNNhIDYRnQDFEJ3r1x", "name": "The Maw", "parent": null, "slot": null}, "#H39Fu7eQrvB4ZxD5U5zXLz": {"book": "mask-of-the-oni", "children": [], "desc": "The PCs should interact primarily with the gunsō leading the squad, Hida Nagahide, so that you do not need to manage names and personalities for each member. Nagahide is a veteran of more than a few expeditions into the Shadowlands. Her face and body bear numerous scars, and although she is a fierce warrior, she knows that caution and planning is what wins battles against the Shadowlands. The bushi accompanying her are similar in outlook and attitude, but they defer to Nagahide due to her greater experience and position of command. They include a mix of Hida and Hiruma bushi.", "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#H39Fu7eQrvB4ZxD5U5zXLz", "name": "Hida Nagahide", "parent": null, "props": [{"dtype": "STRING", "fixed": true, "name": "Type", "value": "Adversary", "vk": "scalar"}, {"dtype": "STRING", "name": "Profile", "value": "If you need a game profile for Hida Nagahide and her squad, use the loyal bushi on page 312 of the Legend of the Five Rings Roleplaying Core Rulebook. The number of bushi in the squad can vary depending on how greatly you want to highlight the fatal horrors of the Shadowlands, but twice the number of PCs is a good starting point.", "vk": "scalar"}, {"dtype": "STRING", "name": "Demeanor", "value": "Cautious veteran", "vk": "scalar"}], "slot": null, "type": "NPC", "typeHash": "#t4540de6f35155c46f41f0"}, "#HKD14HWbpCc1ooWIaVFjWA": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#HKD14HWbpCc1ooWIaVFjWA", "name": "Corrupt the Fallen", "parent": "#0sb0csLT4xayKYIKaXvynp", "props": [{"dtype": "STRING", "name": "Effect", "value": "As an action, Atsumari no Oni may enslave the souls of the dead, which become Tainted. The souls of the deceased must be present, which is normally only true if they died during the current encounter. Additionally, once per round Atsumari no Oni may command any number of enslaved souls to possess an equal number of corpses within range 4. The corpses immediately rise as bushi skeletons (see page 318 of the core rulebook) or zombie peasants (see page 321 of the core rulebook), depending on the condition of the corpse, and they are under Atsumari no Oni's control. To ensure the battle is not impossible, see Encounter Difficulties on page 14 for help determining when and if the oni should use this ability.", "vk": "scalar"}], "slot": null}, "#HfpS0mwWcNggGn4LbpFYJj": {"blocks": [{"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-fall-of-daylight"}], "kw": "AT"}, {"args": [], "body": [{"name": "seat-of", "ref": {"hash": null, "name": "Hiruma"}, "vk": "ref"}, {"args": [{"s": "Shiro Hiruma was the Hiruma family's ancestral seat"}], "kw": "FROM"}, {"name": "haunted-by", "ref": {"hash": null, "name": "Atsumari no Oni"}, "vk": "ref"}, {"args": [{"s": "among the forces that felled Shiro Hiruma was Atsumari no Oni"}], "kw": "FROM"}], "kw": "RELATIONSHIPS"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#HfpS0mwWcNggGn4LbpFYJj", "name": "Shiro Hiruma", "parent": null, "slot": null}, "#Kk0bICKWg5dzm7RKmKiK6I": {"blocks": [{"args": [{"s": "Wall"}], "kw": "TYPE"}, {"args": [{"l": [{"c": "Hida Nagahide", "h": "#H39Fu7eQrvB4ZxD5U5zXLz"}]}], "kw": "NPCS"}], "book": "mask-of-the-oni", "children": [], "desc": "The Kaiu Wall looms over you, one hundred feet of dark stone battlements, redoubts, and watchtowers standing between Rokugan and the Shadowlands beyond. You pass by signs of a recent battle as you approach: wounded Crab bushi being tended by healers and shugenja, burakumin carrying off the dead to be cremated, and yet more warriors cleaning and repairing armor and weapons. More troops stand guard atop the Wall, as the vigil of the Crab against the darkness never ends. Suspicious stares follow you as you pass by, until a sentinel close to the Wall turns to you and barks, \"What is your business here?\"", "file": "l5r5e-0.5-mask-of-the-oni.arc", "form": "DEF", "id": "#Kk0bICKWg5dzm7RKmKiK6I", "name": "Kaiu Wall", "parent": null, "slot": "LOCATIONS"}, "#L5RcxMoO01hirumamasami": {"blocks": [{"args": [{"c": "Person"}], "kw": "IS"}, {"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-fall-of-daylight"}], "kw": "AT"}, {"args": [], "body": [{"name": "member-of", "ref": {"hash": null, "name": "Kaikoga"}, "vk": "ref"}, {"args": [{"s": "Born of the Kaikoga family of the Moth Clan (a Minor Clan devoted to studying Yume-dō, the Realm of Dreams), Masami married into the Hiruma"}], "kw": "FROM"}, {"name": "enemy-of", "ref": {"hash": null, "name": "Atsumari no Oni"}, "vk": "ref"}, {"args": [{"s": "sacrificing her life to send the oni back to Jigoku and herself to Yume-dō"}], "kw": "FROM"}], "kw": "RELATIONSHIPS"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#L5RcxMoO01hirumamasami", "name": "Hiruma Masami", "parent": null, "slot": null}, "#L5RcxMoO02yasukikeiji": {"blocks": [{"args": [{"c": "Person"}], "kw": "IS"}, {"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "part-four-shadow-of-daylight"}], "kw": "AT"}, {"args": [], "body": [{"name": "member-of", "ref": {"hash": null, "name": "Yasuki"}, "vk": "ref"}, {"args": [{"s": "may retrieve the stolen maps of Yasuki Keiji that first drew them into the mission"}], "kw": "FROM"}], "kw": "RELATIONSHIPS"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#L5RcxMoO02yasukikeiji", "name": "Yasuki Keiji", "parent": null, "slot": null}, "#L5RcxMoO03hozumironin": {"blocks": [{"args": [{"c": "Person"}], "kw": "IS"}, {"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-involvement-of-kitsu-sokori"}], "kw": "AT"}, {"args": [], "body": [{"name": "member-of", "ref": {"hash": null, "name": "Hiruma"}, "vk": "ref"}, {"args": [{"s": "a washed-up rōnin named Hozumi, once of the Hiruma family"}], "kw": "FROM"}, {"name": "enemy-of", "ref": {"hash": null, "name": "Kitsu Sokori"}, "vk": "ref"}, {"args": [{"s": "she abducted and tortured a washed-up rōnin named Hozumi"}], "kw": "FROM"}], "kw": "RELATIONSHIPS"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#L5RcxMoO03hozumironin", "name": "Hozumi", "parent": null, "slot": null}, "#L5RcxMoO04kaikogafamily": {"blocks": [{"args": [{"c": "Faction"}], "kw": "IS"}, {"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-fall-of-daylight"}], "kw": "AT"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#L5RcxMoO04kaikogafamily", "name": "Kaikoga", "parent": null, "slot": null}, "#N1WnfOBOWrGonxKItB6LDA": {"blocks": [{"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "the-involvement-of-kitsu-sokori"}], "kw": "AT"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#N1WnfOBOWrGonxKItB6LDA", "name": "Slow Tide Harbor", "parent": null, "slot": null}, "#NJEUj7tZcSvCsqu8EzD15h": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#NJEUj7tZcSvCsqu8EzD15h", "name": "Whispers in Blood", "parent": "#lKIp7ISJxHs1XKKEPNzpNZ", "props": [{"dtype": "STRING", "name": "Effect", "value": "In a vile fusion of her Kitsu ancestor-speaking and mahō abilities, Sokori can use the blood of a mortal to perceive much about that mortal's flaws and weaknesses—and then use that information against them. Sokori must have access to the blood of a mortal; enough to coat the blade of a small knife is sufficient. As a downtime activity, she makes a TN 2 Theology (Water) check; if it is successful, she learns all of that mortal's advantages and disadvantages.", "vk": "scalar"}], "slot": null}, "#gl7ahDmCsOMD3WUvOXhPfr": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#gl7ahDmCsOMD3WUvOXhPfr", "name": "Mahō-Sensei", "parent": "#lKIp7ISJxHs1XKKEPNzpNZ", "props": [{"dtype": "STRING", "name": "Effect", "value": "Sokori can use any mahō technique in the core rulebook (beginning on page 224). She generally uses Unholy Fervor to empower her minions and Grip of Anguish on any PCs attempt to engage her directly. At the GM's discretion, she may also have access to the new mahō techniques in Shadowlands (beginning on page 116).", "vk": "scalar"}], "slot": null}, "#k0fyufj3ODA21YOZWPZ59X": {"blocks": [{"args": [{"s": "Castle"}], "kw": "TYPE"}, {"args": [{"s": "Shadowlands ruin (heavily Tainted)"}], "kw": "DANGER_LEVEL"}, {"args": [{"l": [{"c": "Kitsu Sokori"}, {"c": "Atsumari no Oni", "h": "#0sb0csLT4xayKYIKaXvynp"}]}], "kw": "NPCS"}], "book": "mask-of-the-oni", "children": [], "desc": "Daylight Castle, the ultimate destination of the PCs in Mask of the Oni, is an ancient castle that has suffered not only from the attack by the Maw that led to its downfall, but also from the corruption of the Shadowlands in the centuries since. The combined effects of battle damage, the passage of time, and the Taint of Jigoku have rendered the place ominous and confusing, even for Crab samurai.\n\nAs you round a rocky spur that thrusts out from a line of jagged, barren hills, you see the walls and towers of a fortress looming ahead of you, dominating the blasted landscape around it. This is Shiro Hiruma, once the ancestral home and seat of power of the Hiruma family. Now, it is a bleak ruin, with gaping holes where walls have slumped and collapsed. The watchtowers and the great keep inside the walls claw at the darkening sky like ghastly fingers. A brooding stillness hangs over the place; the air is heavy with an oppressive sense of expectation, as though something cataclysmic could happen at any moment.", "file": "l5r5e-0.5-mask-of-the-oni.arc", "form": "DEF", "id": "#k0fyufj3ODA21YOZWPZ59X", "name": "Shiro Hiruma", "parent": null, "slot": "LOCATIONS"}, "#lKIp7ISJxHs1XKKEPNzpNZ": {"blocks": [{"ent": "#gl7ahDmCsOMD3WUvOXhPfr"}, {"ent": "#ltZ2AxpFw1Plrfv1kYf0Y7"}, {"ent": "#NJEUj7tZcSvCsqu8EzD15h"}], "book": "mask-of-the-oni", "children": ["#gl7ahDmCsOMD3WUvOXhPfr", "#ltZ2AxpFw1Plrfv1kYf0Y7", "#NJEUj7tZcSvCsqu8EzD15h"], "desc": "Kitsu Sokori does not favor direct confrontation. Throughout her sordid history, she has focused on indirect and insidious ways of defeating her foes. This holds true during the final confrontation (and any prior confrontation with her, if there is one).\n\nAlthough she has access to various mahō effects that can cause direct damage, Sokori generally relies on her undead servants to engage directly in combat. In the meantime, she exploits the PCs' flaws and weaknesses, and any potential conflict among them, to cause friction and dissent. That was why she had undead attack the PCs earlier, after all, in order to collect their blood and use it to learn their secrets. If this was successful, Sokori knows each PC's disadvantages, and she uses these as much as possible. For example, by using an action, she can employ variants of the Incite Haunting or Sinful Whispers mahō techniques to torment the PCs, as in the following examples:\n\nIf a PC has the Phobia anxiety, Sokori causes an illusory manifestation of the object of that phobia.\n\nIf a PC has the Paranoia anxiety, Sokori silently whispers to them that the other PCs plan to sacrifice them to survive the confrontation.\n\nIf two PCs are from clans that are currently hostile toward each other or at war, Sokori can sow discord between those PCs. If a target PC fails a TN 3 Meditation check (Void 2), they suffer 3 strife.\n\nIf a PC has the Dark Secret anxiety, Sokori speaks in the PC's mind, threatening to reveal it. Alternatively, she may do so out loud, thereby letting the other PCs know that the target may have a Dark Secret, but not what it is. If she believes it will cause more tension and dissent to do so, she might even reveal the PC's Dark Secret outright.\n\nNotwithstanding the above, if the indirect approach fails, or if she has been unable to learn information about the PCs that can help her, Sokori resorts to using mahō to directly deal damage to her opponents.\n\nAssuming that she doesn't actually defeat the PCs, it is expected that Sokori dies by the end of the confrontation. However, if the GM would prefer to have her survive and be a future antagonist in their campaign, she may escape.", "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#lKIp7ISJxHs1XKKEPNzpNZ", "name": "Kitsu Sokori", "parent": null, "props": [{"dtype": "STRING", "fixed": true, "name": "Type", "value": "Adversary", "vk": "scalar"}, {"dtype": "INTEGER", "name": "Combat Conflict Rank", "value": 8, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Intrigue Conflict Rank", "value": 6, "vk": "scalar"}, {"fields": [{"dtype": "INTEGER", "name": "Air", "value": 3, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Earth", "value": 4, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Fire", "value": 3, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Water", "value": 4, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Void", "value": 4, "vk": "scalar"}], "name": "Rings", "vk": "def"}, {"dtype": "STRING", "name": "Demeanor", "value": "Shrewd", "vk": "scalar"}, {"dtype": "INTEGER", "name": "Endurance", "value": 16, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Composure", "value": 12, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Focus", "value": 7, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Vigilance", "value": 4, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Honor", "value": 1, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Glory", "value": 25, "vk": "scalar"}, {"dtype": "INTEGER", "name": "Status", "value": 5, "vk": "scalar"}, {"items": [{"s": "Artisan 0"}, {"s": "Martial 2"}, {"s": "Scholar 3"}, {"s": "Social 3"}, {"s": "Trade 2"}], "name": "Skills", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Sixth Sense — Scholar; Spiritual"}, {"s": "Indomitable Will — Scholar; Interpersonal"}], "name": "Advantages", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Whispers of Cruelty — Social; Infamy"}, {"s": "Shadowlands Taint — Social; Spiritual"}], "name": "Disadvantages", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Corrupted Wakizashi: Range 0–1, Damage 4, Deadliness 5/7, Ceremonial, Razor-Edged, Unholy"}, {"s": "Sacrificial Knife: Range 0, Damage 2, Deadliness 4, Concealable, Mundane, Razor-Edged, Unholy"}], "name": "Favored Weapons", "of": "STRING", "ofWord": true, "vk": "list"}, {"items": [{"s": "Gear (equipped): Profane robes (Physical 1, Supernatural 4), scroll satchel containing mahō scrolls and the stolen maps of Yasuki Keiji"}], "name": "Gear", "of": "STRING", "ofWord": true, "vk": "list"}], "slot": null, "type": "NPC", "typeHash": "#t4540de6f35155c46f41f0"}, "#ltZ2AxpFw1Plrfv1kYf0Y7": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#ltZ2AxpFw1Plrfv1kYf0Y7", "name": "Walking the Way", "parent": "#lKIp7ISJxHs1XKKEPNzpNZ", "props": [{"dtype": "STRING", "name": "Effect", "value": "Sokori can draw upon her Kitsu heritage to part the veil separating the Spirit Realms from Ningen-dō, then pass through to emerge in a new place. For the purposes of this adventure, Sokori is presumed to use this ability only once, the first time the PCs encounter her, to escape the confrontation. As a Movement and Support action, Sokori begins stepping out of the Realm of Mortals, her form shimmering slightly. At the start of her next turn, she vanishes and reappears in another location at range 0–6 of her prior location (including a location out of line of sight).", "vk": "scalar"}], "slot": null}, "#vYRQSaECZpWt7nmleTn86t": {"blocks": [{"args": [{"s": "l5r5e-0.5-mask-of-the-oni.lore"}], "kw": "SOURCE"}, {"args": [{"s": "part-two-arriving-at-the-kaiu-wall"}], "kw": "AT"}], "book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni.codex", "form": "ENTITY", "id": "#vYRQSaECZpWt7nmleTn86t", "name": "Kaiu Wall", "parent": null, "slot": null}, "#xN38GbiHCH6QjbMuENI7EL": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#xN38GbiHCH6QjbMuENI7EL", "name": "Aura of Dread", "parent": "#0sb0csLT4xayKYIKaXvynp", "props": [{"dtype": "STRING", "name": "Effect", "value": "Atsumari no Oni's malign ability to corrupt and enslave the souls of the fallen surrounds it with a chilling aura that saps the wills of those who would risk their lives to confront it in close melee combat. When a character within range 3 attempts to move closer to Atsumari no Oni, they must resist with a TN 2 Meditation check (Earth 1, Air 4) or suffer the Disoriented condition and remain at their current distance from the oni. Once a character succeeds on this check, they do not have to make it again during the current scene.", "vk": "scalar"}], "slot": null}, "#zNdk7Evn1NAw7w6rbFAKYw": {"book": "mask-of-the-oni", "children": [], "file": "l5r5e-0.5-mask-of-the-oni-cast.ttrpg", "form": "DEF", "id": "#zNdk7Evn1NAw7w6rbFAKYw", "name": "Horror of Jigoku", "parent": "#0sb0csLT4xayKYIKaXvynp", "props": [{"dtype": "STRING", "name": "Effect", "value": "Atsumari no Oni is an Otherworldly, Tainted being of silhouette 4. After any character performs a successful Attack action that deals 0 damage to the oni (after resistance is applied), that character suffers 3 strife.", "vk": "scalar"}], "slot": null}}, "src": "data/mask-of-the-oni.js"};var T=window.L5R5E=window.L5R5E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
